'use client'

import { forwardRef, useId, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import Image from 'next/image'
import { HugeiconsIcon } from '@hugeicons/react'
import { ArrowRight02Icon } from '@hugeicons/core-free-icons'
import { CtaAction, CtaActionIcon } from '@/components/blocks/cta/cta'
import { PhoneMockupCard } from '@/components/illustration/phone-mockup'
import { cn } from '@/lib/utils'

export interface CtaSplitProps extends Omit<ComponentPropsWithoutRef<'section'>, 'title'> {
  title?: ReactNode
  description?: ReactNode
  actionLabel?: string
  actionHref?: string
  actionIcon?: ReactNode
  imageSrc?: string
  imageDarkSrc?: string
  imageAlt?: string
  media?: ReactNode
}

function ScreenSkeleton() {
  return (
    <div aria-hidden="true" className="flex h-full flex-col gap-3 bg-(--color-bg) px-4 pt-12">
      <span className="h-3 w-24 rounded-md bg-(--color-fg)/10" />
      <span className="aspect-4/3 w-full rounded-md bg-(--color-fg)/7" />
      <span className="h-2 w-4/5 rounded-md bg-(--color-fg)/7" />
      <span className="h-2 w-3/5 rounded-md bg-(--color-fg)/7" />
    </div>
  )
}

function PhoneScreen({ src, darkSrc, alt }: { src?: string; darkSrc?: string; alt: string }) {
  if (!src) return <ScreenSkeleton />

  return (
    <div className="relative h-full w-full bg-(--color-bg)">
      <div className="absolute inset-x-0 top-10 bottom-0">
        <Image
          src={src}
          alt={alt}
          fill
          sizes="256px"
          className={cn('object-cover object-top', darkSrc && 'dark:hidden')}
        />
        {darkSrc && (
          <Image
            src={darkSrc}
            alt={alt}
            fill
            sizes="256px"
            className="hidden object-cover object-top dark:block"
          />
        )}
      </div>
    </div>
  )
}

export const CtaSplit = forwardRef<HTMLElement, CtaSplitProps>(
  (
    {
      title = 'Blocks that fit every screen',
      description = 'Every block starts at phone width and grows into wide layouts. Check it on a device, then copy it into your app.',
      actionLabel = 'Browse blocks',
      actionHref = '#',
      actionIcon = <HugeiconsIcon icon={ArrowRight02Icon} size={16} strokeWidth={1.5} />,
      imageSrc,
      imageDarkSrc,
      imageAlt = 'App screen on a phone',
      media,
      className,
      ...props
    },
    ref,
  ) => {
    const headingId = useId()

    return (
      <section
        ref={ref}
        aria-labelledby={headingId}
        className={cn(
          'w-full overflow-hidden rounded-md border border-(--color-border) bg-(--color-bg)',
          className,
        )}
        {...props}
      >
        <div className="grid items-center gap-8 pt-12 sm:pt-16 lg:grid-cols-[1.05fr_0.95fr] lg:pt-0">
          <div className="mx-auto max-w-xl px-6 text-center sm:px-8 lg:mx-0 lg:py-16 lg:ps-14 lg:text-start">
            <h2
              id={headingId}
              className="text-balance text-2xl font-normal tracking-tight text-(--color-fg) md:text-3xl"
            >
              {title}
            </h2>
            {description && (
              <p className="mt-4 text-pretty text-sm text-(--color-muted) md:text-base">
                {description}
              </p>
            )}
            {actionLabel && (
              <div className="mt-8 flex justify-center lg:justify-start">
                <CtaAction href={actionHref}>
                  {actionLabel}
                  {actionIcon && <CtaActionIcon>{actionIcon}</CtaActionIcon>}
                </CtaAction>
              </div>
            )}
          </div>
          <div className="flex items-end justify-center self-stretch lg:justify-end lg:pe-14 lg:pt-12">
            {media ?? (
              <PhoneMockupCard visibleRatio={0.55}>
                <PhoneScreen src={imageSrc} darkSrc={imageDarkSrc} alt={imageAlt} />
              </PhoneMockupCard>
            )}
          </div>
        </div>
      </section>
    )
  },
)
CtaSplit.displayName = 'CtaSplit'

'use client'

import { forwardRef, useId, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

export interface CtaProps extends Omit<ComponentPropsWithoutRef<'section'>, 'title'> {
  title: ReactNode
  description?: ReactNode
  actions?: ReactNode
}

export const Cta = forwardRef<HTMLElement, CtaProps>(
  ({ title, description, actions, className, ...props }, ref) => {
    const headingId = useId()

    return (
      <section
        ref={ref}
        aria-labelledby={headingId}
        className={cn(
          'w-full rounded-md border border-(--color-border) bg-(--color-bg)',
          className,
        )}
        {...props}
      >
        <div className="mx-auto flex max-w-xl flex-col items-center px-6 py-16 text-center md:py-20">
          <h2
            id={headingId}
            className="text-balance text-2xl font-normal tracking-tight text-(--color-fg) md:text-3xl"
          >
            {title}
          </h2>
          {description && (
            <p className="mt-4 text-pretty text-sm text-(--color-muted) md:text-base">
              {description}
            </p>
          )}
          {actions && (
            <div className="mt-8 flex w-full flex-col items-stretch justify-center gap-3 sm:w-auto sm:flex-row sm:items-center">
              {actions}
            </div>
          )}
        </div>
      </section>
    )
  },
)
Cta.displayName = 'Cta'

export const ctaActionVariants = cva(
  'group/cta-action inline-flex h-11 items-center justify-center gap-2 rounded-md px-5 text-sm transition-[background-color,border-color,scale] duration-(--motion-dur-fast) ease active:scale-[0.97] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg) motion-reduce:transition-none motion-reduce:active:scale-100',
  {
    variants: {
      variant: {
        primary: 'bg-(--color-fg) text-(--color-bg) hover:bg-(--color-fg)/88',
        secondary:
          'border border-(--color-border) text-(--color-fg) hover:border-(--color-border-strong) hover:bg-(--color-fg)/5',
      },
    },
    defaultVariants: { variant: 'primary' },
  },
)

export interface CtaActionProps
  extends ComponentPropsWithoutRef<'a'>, VariantProps<typeof ctaActionVariants> {
  asChild?: boolean
}

export const CtaAction = forwardRef<HTMLAnchorElement, CtaActionProps>(
  ({ asChild, variant, className, ...props }, ref) => {
    const Comp = asChild ? Slot : 'a'

    return <Comp ref={ref} className={cn(ctaActionVariants({ variant }), className)} {...props} />
  },
)
CtaAction.displayName = 'CtaAction'

export function CtaActionIcon({ children }: { children: ReactNode }) {
  return (
    <span
      aria-hidden="true"
      className="inline-flex transition-[translate] duration-(--motion-dur-base) ease-(--motion-ease-in-out) rtl:-scale-x-100 motion-safe:group-hover/cta-action:translate-x-1 motion-safe:group-focus-visible/cta-action:translate-x-1 motion-safe:rtl:group-hover/cta-action:-translate-x-1 motion-safe:rtl:group-focus-visible/cta-action:-translate-x-1 motion-reduce:transition-none"
    >
      {children}
    </span>
  )
}

'use client'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { cn } from '@/lib/utils'

const mockupChassisVariants = {
  gray: {
    frame: 'bg-(--color-border)',
    button: 'bg-(--color-border)',
  },
  titanium: {
    frame: 'bg-(--color-foreground)',
    button: 'bg-(--color-foreground)',
  },
} as const

type MockupChassisVariant = keyof typeof mockupChassisVariants

const CHASSIS_ASPECT_RATIO = 70.6 / 146.6

type PhoneMockupCardProps = Readonly<
  ComponentPropsWithoutRef<'div'> & {
    variant?: MockupChassisVariant
    visibleRatio?: number
    showDynamicIsland?: boolean
  }
>

const sideControlClass = (color: string) => cn('absolute w-0.5 rounded-l-sm', color)

function SideControls({
  frame,
}: Readonly<{
  frame: (typeof mockupChassisVariants)[MockupChassisVariant]
}>) {
  return (
    <>
      <div
        className={cn(sideControlClass(frame.button), 'top-[15.5%] -left-0.5 h-[3.2%]')}
        aria-hidden="true"
      />
      <div
        className={cn(sideControlClass(frame.button), 'top-[21%] -left-0.5 h-[7.2%]')}
        aria-hidden="true"
      />
      <div
        className={cn(sideControlClass(frame.button), 'top-[30.5%] -left-0.5 h-[7.2%]')}
        aria-hidden="true"
      />
      <div
        className={cn(
          sideControlClass(frame.button),
          'top-[23%] -right-0.5 h-[11.5%] rounded-l-none rounded-r-sm',
        )}
        aria-hidden="true"
      />
    </>
  )
}

function MockupScreen({
  children,
  showDynamicIsland,
}: Readonly<{
  children: ReactNode
  showDynamicIsland: boolean
}>) {
  return (
    <div className="relative h-full w-full overflow-hidden rounded-[2.5rem] bg-black">
      <div className="absolute inset-[3.5px] overflow-hidden rounded-[2.3rem] bg-white">
        <div className="relative h-full w-full">{children}</div>
        {showDynamicIsland && (
          <div
            className="absolute top-[9px] left-1/2 z-20 h-5 w-[66px] -translate-x-1/2 rounded-full bg-black"
            aria-hidden="true"
          >
            <div
              className="absolute top-1/2 right-[5px] block h-2 w-2 shrink-0 -translate-y-1/2 rounded-full bg-(--color-muted)/40"
              aria-hidden="true"
            />
          </div>
        )}
        <div
          className="absolute bottom-[5.5px] left-1/2 z-20 h-[3px] w-[32%] -translate-x-1/2 rounded-full bg-black/20"
          aria-hidden="true"
        />
      </div>
    </div>
  )
}

export const PhoneMockupCard = forwardRef<HTMLDivElement, PhoneMockupCardProps>(
  (
    {
      className,
      children,
      variant = 'titanium',
      visibleRatio = 1,
      showDynamicIsland = true,
      style,
      ...props
    },
    ref,
  ) => {
    const frame = mockupChassisVariants[variant]
    const ratio = Math.min(1, Math.max(0, visibleRatio))
    const isCropped = ratio < 1

    const phoneFrameClassName = cn('relative w-64 rounded-[2.6rem] p-0.5', frame.frame)

    if (!isCropped) {
      return (
        <div
          ref={ref}
          data-slot="phone-mockup-card"
          data-variant={variant}
          className={cn(phoneFrameClassName, 'aspect-[70.6/146.6]', className)}
          style={style}
          {...props}
        >
          <SideControls frame={frame} />
          <MockupScreen showDynamicIsland={showDynamicIsland}>{children}</MockupScreen>
        </div>
      )
    }

    return (
      <div
        ref={ref}
        data-slot="phone-mockup-card"
        data-variant={variant}
        data-visible-ratio={ratio}
        className={cn('relative w-65 overflow-hidden', className)}
        style={{ aspectRatio: `${CHASSIS_ASPECT_RATIO / ratio}`, ...style }}
        {...props}
      >
        <div className="absolute inset-0 right-0.5 left-0.5 overflow-hidden">
          <div
            className={cn(phoneFrameClassName, 'w-full shrink-0')}
            style={{ height: `${100 / ratio}%` }}
          >
            <MockupScreen showDynamicIsland={showDynamicIsland}>{children}</MockupScreen>
          </div>
        </div>
        <div
          className="pointer-events-none absolute top-0 left-0.5 z-10 w-64 shrink-0"
          style={{ height: `${100 / ratio}%` }}
        >
          <SideControls frame={frame} />
        </div>
      </div>
    )
  },
)

PhoneMockupCard.displayName = 'PhoneMockupCard'
